<script setup lang="ts">
import axios from 'axios';
import { computed, onMounted, ref } from 'vue';
import { RouterLink } from 'vue-router';
import http from '@/api/http';
import { useAuthStore } from '@/stores/auth';

interface PermissionRecord { id: number; name: string; guard_name: string; group: string; group_key: string; roles_count: number; other_roles_count: number; users_count: number; is_protected: boolean; created_at: string | null; deleted_at: string | null }
interface PaginationMeta { current_page: number; last_page: number; total: number }
interface ApiError { message?: string; errors?: Record<string, string[]> }
const auth = useAuthStore();
const permissions = ref<PermissionRecord[]>([]);
const search = ref('');
const group = ref('');
const guard = ref('');
const groups = ref<string[]>([]);
const loading = ref(false);
const processing = ref(false);
const action = ref('');
const selectedIds = ref<number[]>([]);
const message = ref('');
const errorMessage = ref('');
const pagination = ref<PaginationMeta>({ current_page: 1, last_page: 1, total: 0 });
const canRestore = auth.can('permissions.restore');
const canForceDelete = auth.can('permissions.force_delete');
const selectableIds = computed(() => permissions.value.filter((item) => !item.is_protected && item.other_roles_count === 0 && item.users_count === 0).map((item) => item.id));
const allSelected = computed(() => selectableIds.value.length > 0 && selectableIds.value.every((id) => selectedIds.value.includes(id)));
function handleError(error: unknown): void { errorMessage.value = axios.isAxiosError<ApiError>(error) ? error.response?.data?.message ?? 'Unable to complete the action.' : 'Unable to complete the action.'; }
async function fetchPermissions(page = 1): Promise<void> { loading.value = true; selectedIds.value = []; try { const response = await http.get('/permissions/trash', { params: { page, per_page: 15, search: search.value || undefined, group: group.value || undefined, guard: guard.value || undefined } }); permissions.value = response.data.data; pagination.value = response.data.meta; groups.value = Array.from(new Set([...groups.value, ...permissions.value.map((item) => item.group_key)])).sort(); } catch (error) { handleError(error); } finally { loading.value = false; } }
async function fetchGroups(): Promise<void> { try { const response = await http.get('/permissions', { params: { per_page: 100 } }); groups.value = Array.from(new Set((response.data.data as PermissionRecord[]).map((item) => item.group_key))).sort(); } catch (error) { handleError(error); } }
function toggleAll(event: Event): void { selectedIds.value = (event.target as HTMLInputElement).checked ? permissions.value.filter((item) => !item.is_protected && item.other_roles_count === 0 && item.users_count === 0).map((item) => item.id) : []; }
function toggleSelected(id: number, event: Event): void { selectedIds.value = (event.target as HTMLInputElement).checked ? [...selectedIds.value, id] : selectedIds.value.filter((value) => value !== id); }
function formatDate(value: string | null): string { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'; }
async function runAction(next: 'restore' | 'force_delete', ids: number[]): Promise<void> { if (!ids.length) return; const label = next === 'restore' ? 'restore' : 'permanently delete'; if (!window.confirm(`Are you sure you want to ${label} ${ids.length} permission(s)?`)) return; processing.value = true; try { await http.post('/permissions/bulk-action', { action: next, ids }); message.value = `${ids.length} permission(s) ${next === 'restore' ? 'restored' : 'permanently deleted'} successfully.`; action.value = ''; await fetchPermissions(pagination.value.current_page); } catch (error) { handleError(error); } finally { processing.value = false; } }
async function applyBulkAction(): Promise<void> { if (action.value === 'restore' || action.value === 'force_delete') await runAction(action.value, selectedIds.value); }
async function restorePermission(permission: PermissionRecord): Promise<void> { await runAction('restore', [permission.id]); }
async function forcePermission(permission: PermissionRecord): Promise<void> { await runAction('force_delete', [permission.id]); }
onMounted(async () => Promise.all([fetchPermissions(), fetchGroups()]));
</script>

<template>
    <div class="module-page"><div class="module-page-heading"><div class="module-title-wrap"><span class="module-title-icon module-title-icon-danger"><i class="bi bi-trash3-fill"></i></span><div><h3 class="mb-1">Trashed Permissions</h3><p class="text-body-secondary mb-0">Restore permissions or permanently delete unused permissions.</p></div></div><nav class="module-breadcrumb"><RouterLink :to="{ name: 'dashboard' }"><i class="bi bi-house-fill"></i></RouterLink><i class="bi bi-chevron-right"></i><span>Access Control</span><i class="bi bi-chevron-right"></i><RouterLink :to="{ name: 'permissions' }">Permissions</RouterLink><i class="bi bi-chevron-right"></i><strong>Trash</strong></nav></div>
        <div class="module-toolbar"><RouterLink :to="{ name: 'permissions' }" class="btn btn-secondary"><i class="bi bi-arrow-left me-1"></i>Back to Permissions</RouterLink><div class="bulk-toolbar"><select v-model="action" class="form-select"><option value="">-- Bulk Actions --</option><option v-if="canRestore" value="restore">Restore</option><option v-if="canForceDelete" value="force_delete">Force Delete</option></select><button class="btn btn-secondary" :disabled="!selectedIds.length || !action || processing" @click="applyBulkAction">{{ processing ? 'Applying...' : 'APPLY' }}</button><span v-if="selectedIds.length" class="selected-count">{{ selectedIds.length }} selected</span></div></div>
        <div v-if="message" class="alert alert-success">{{ message }}</div><div v-if="errorMessage" class="alert alert-danger">{{ errorMessage }}</div>
        <div class="card module-filter-card"><div class="card-body"><form class="row g-3 align-items-end" @submit.prevent="fetchPermissions(1)"><div class="col-6 col-md-2"><label class="form-label">GUARD NAME</label><select v-model="guard" class="form-select"><option value="">All Guards</option><option value="web">web</option></select></div><div class="col-6 col-md-3"><label class="form-label">GROUP NAME</label><select v-model="group" class="form-select"><option value="">All Groups</option><option v-for="item in groups" :key="item" :value="item">{{ item }}</option></select></div><div class="col-12 col-md-5"><label class="form-label">SEARCH TRASHED</label><input v-model.trim="search" class="form-control" type="search" placeholder="Search trashed permission name..."></div><div class="col-12 col-md-2 d-flex gap-2"><button class="btn btn-primary flex-fill" type="submit"><i class="bi bi-search"></i></button><button class="btn btn-outline-danger flex-fill" type="button" @click="search = ''; group = ''; guard = ''; fetchPermissions(1)"><i class="bi bi-arrow-counterclockwise"></i>Reset</button></div></form></div></div>
        <div class="card module-list-card"><div class="card-header"><h5 class="card-title text-danger"><i class="bi bi-trash3 me-2"></i>Trash Bin</h5></div><div class="table-responsive"><table class="table table-hover align-middle module-table mb-0"><thead><tr><th class="text-center"><input class="form-check-input" type="checkbox" :checked="allSelected" :disabled="loading" @change="toggleAll"></th><th>ID</th><th>Permission Name</th><th>Guard Name</th><th>Group Name</th><th>Deleted At</th><th class="text-end">Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="text-center py-5"><span class="spinner-border spinner-border-sm me-2"></span>Loading trash...</td></tr><tr v-else-if="!permissions.length"><td colspan="7" class="module-empty"><i class="bi bi-key d-block mb-2"></i>No Trashed Permissions Found</td></tr><template v-else><tr v-for="permission in permissions" :key="permission.id"><td class="text-center"><input class="form-check-input" type="checkbox" :checked="selectedIds.includes(permission.id)" :disabled="permission.is_protected || permission.other_roles_count > 0 || permission.users_count > 0" @change="toggleSelected(permission.id, $event)"></td><td>#{{ permission.id }}</td><td><code>{{ permission.name }}</code><span v-if="permission.is_protected" class="badge text-bg-danger ms-2">Protected</span></td><td><span class="badge text-bg-secondary">{{ permission.guard_name }}</span></td><td><span class="badge text-bg-light border">{{ permission.group }}</span></td><td>{{ formatDate(permission.deleted_at) }}</td><td class="text-end"><div class="btn-group btn-group-sm"><button v-if="canRestore" class="btn btn-outline-success" title="Restore" :disabled="processing" @click="restorePermission(permission)"><i class="bi bi-arrow-counterclockwise"></i></button><button v-if="canForceDelete" class="btn btn-outline-danger" title="Force Delete" :disabled="processing || permission.is_protected || permission.other_roles_count > 0 || permission.users_count > 0" @click="forcePermission(permission)"><i class="bi bi-x-octagon"></i></button></div></td></tr></template></tbody></table></div><div class="card-footer d-flex justify-content-between align-items-center"><span class="small text-body-secondary">{{ pagination.total }} trashed permissions</span><div class="btn-group btn-group-sm"><button class="btn btn-outline-secondary" :disabled="pagination.current_page <= 1 || loading" @click="fetchPermissions(pagination.current_page - 1)">Previous</button><button class="btn btn-outline-secondary" disabled>Page {{ pagination.current_page }} of {{ pagination.last_page }}</button><button class="btn btn-outline-secondary" :disabled="pagination.current_page >= pagination.last_page || loading" @click="fetchPermissions(pagination.current_page + 1)">Next</button></div></div></div>
    </div>
</template>
